/* The UI's vocabulary, fetched rather than hard-coded.
 *
 * data/config.json is generated by docs/build_data.py from docs/vocabulary.py
 * and carries a count for every facet, so the page can build its chips, options
 * and columns from the corpus it is actually browsing. Nothing here is a
 * literal: change a facet in vocabulary.py, rebuild, and the UI follows. */

let config = null;

export async function loadConfig() {
  const res = await fetch("data/config.json");
  if (!res.ok) throw new Error("HTTP " + res.status + " loading data/config.json");
  config = await res.json();
  return config;
}

/* Only valid after loadConfig() resolves — boot awaits it before rendering. */
export const cfg = () => config;

/* Facets the corpus can actually satisfy. A vocabulary entry counted at zero is
   a filter that would only ever return nothing, so it never reaches the page. */
export const usable = (list) => (list || []).filter((o) => o.count !== 0);

export const PAGE = () => (config && config.page) || 120;

export const patternDisplay = (name) =>
  (config && config.patternDisplay && config.patternDisplay[name]) || name;
